// SAL-35: helpers for dynamic REST lookup endpoints in the Custom Master Data list.

const PLACEHOLDER_PATTERN = /\[([^\]]+)\]/g;

type EndpointRecord = {
  url?: string | null;
  params?: string | null;
  body?: string | null;
  headers?: string | null;
};

// The backend fills [Name] placeholders in url, params, body and headers.
export function getPlaceholders(record: EndpointRecord): string[] {
  const names = new Set<string>();
  [record.url, record.params, record.body, record.headers].forEach((part) => {
    if (!part) {
      return;
    }
    for (const match of String(part).matchAll(PLACEHOLDER_PATTERN)) {
      names.add(match[1]);
    }
  });
  return [...names].sort();
}

export function parseSampleValues(
  sample_values: string | null | undefined,
): Record<string, string> {
  try {
    const values = sample_values ? JSON.parse(sample_values) : {};
    return values && typeof values === 'object' && !Array.isArray(values)
      ? values
      : {};
  } catch (e) {
    return {};
  }
}
